<section class="card table-card"><div class="table-scroll"><table><thead><tr><th>用户名</th><th>角色</th><th>状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><strong><?= e($r['username']) ?></strong><div class="muted">ID <?= (int)$r['id'] ?></div></td><td><?= e($r['role']==='owner'?'所有者':'管理员') ?></td><td><span class="badge <?= $r['is_active']?'ok':'muted' ?>"><?= $r['is_active']?'启用':'停用' ?></span></td><td><?= e($r['last_login_at'] ?: '尚未登录') ?><div class="muted"><?= e($r['last_login_ip'] ?: '') ?></div></td><td class="ops"><form method="post" action="/admin/admins/<?= (int)$r['id'] ?>/toggle"><?= csrf_field() ?><button class="btn ghost"><?= $r['is_active']?'停用':'启用' ?></button></form><form method="post" action="/admin/admins/<?= (int)$r['id'] ?>/delete" onsubmit="return confirm('确认删除该管理员？')"><?= csrf_field() ?><button class="btn ghost danger">删除</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card"><h2>新增管理员</h2><form method="post" action="/admin/admins/create"><?= csrf_field() ?><div class="form-grid"><label>用户名<input name="username" type="text" autocomplete="off" required></label><label>初始密码<input name="password" type="password" minlength="6" autocomplete="new-password" required><span class="hint">至少 6 位。</span></label><label>角色<select name="role"><option value="admin">管理员：管理授权，不能管理管理员</option><option value="owner">所有者：全部权限</option></select></label></div><div class="form-actions"><button class="btn" type="submit">创建管理员</button></div></form></section>
<section class="card"><h2>重置管理员密码</h2><form method="post" action="/admin/admins/password-reset"><?= csrf_field() ?><div class="form-grid"><label>管理员 ID<input name="id" type="number" min="1" required><span class="hint">填写上方列表中的管理员 ID。</span></label><label>新密码<input name="password" type="password" minlength="6" autocomplete="new-password" required></label></div><div class="form-actions"><button class="btn ghost" type="submit">重置管理员密码</button></div></form></section>
